message.content:
{
  "css": ".day-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.day-tabs button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 64px;
  height: 32px;
  padding: 0 12px;
  font-size: 14px;
  font-weight: 700;
  line-height: 1;
  border-radius: 16px;
  border: 1px solid var(--border, #e8e8e8);
  background-color: #fff;
  color: var(--ink, #111);
  cursor: pointer;
  white-space: nowrap;
}

.day-tabs button[aria-pressed="true"] {
  background-color: var(--ink, #111);
  color: #fff;
  border-color: transparent;
}"
}
